CREATE TABLE p_payment_records(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES p_proposals(id),revision INTEGER NOT NULL,currency TEXT NOT NULL,cents INTEGER NOT NULL CHECK(cents>0),method TEXT NOT NULL CHECK(method IN ('stripe','check','wire','ach_credit')),provider_charge TEXT UNIQUE,reference TEXT NOT NULL,received_on TEXT,recorded_by TEXT NOT NULL REFERENCES oa_operators(id),recorded_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE p_refunds(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES p_payment_records(id),cents INTEGER NOT NULL CHECK(cents>0),reason TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('reserved','succeeded','pending_provider','needs_review')),provider_refund TEXT,requested_by TEXT NOT NULL REFERENCES oa_operators(id),requested_at INTEGER NOT NULL,completed_at INTEGER);
